int main(){float f[16]={0,.5f,1,1.5f,2,3,4,6,-0.f,-.5f,-1,-1.5f,-2,-3,-4,-6},sf[128];for(int i=0;i<128;i++){int e=i>>3,m=i&7;sf[i]=e?ldexpf(1.f+float(m)/8.f,e-7):float(m)/512.f;}CK(cudaMemcpyToSymbol(E2,f,sizeof f));CK(cudaMemcpyToSymbol(SCALE,sf,sizeof sf));uint32_t wlut[16],xlut[16];for(int i=0;i<16;i++){int a=i&3,b=i>>2;float v=(a==3?-1:a)+512.f*(b==3?-1:b);if(a==2||b==2)wlut[i]=0x7fffffffU;else{memcpy(wlut+i,&v,4);if(wlut[i]&8191U)return 3;}float z=2*f[i];memcpy(xlut+i,&z,4);if(xlut[i]&8191U)return 3;}std::mt19937 rng(20261014);std::vector<uint8_t>w(M*16,0),x(N*16),sc(N*2);int codes[3]={0,1,3};for(int r=0;r<M;r++)for(int k=0;k<K;k++)w[r*16+k/2]|=uint8_t(codes[rng()%3]|(codes[rng()%3]<<2))<<(4*(k&1));for(auto&v:x)v=uint8_t(rng());for(auto&v:sc)v=uint8_t(0x30+(rng()&15));uint8_t *dw,*dx,*ds;uint32_t*dlw,*dlx;unsigned long long*bad;CK(cudaMalloc(&dw,w.size()));CK(cudaMalloc(&dx,x.size()));CK(cudaMalloc(&ds,sc.size()));CK(cudaMalloc(&dlw,64));CK(cudaMalloc(&dlx,64));CK(cudaMalloc(&bad,32));CK(cudaMemcpy(dw,w.data(),w.size(),cudaMemcpyHostToDevice));CK(cudaMemcpy(dx,x.data(),x.size(),cudaMemcpyHostToDevice));CK(cudaMemcpy(ds,sc.data(),sc.size(),cudaMemcpyHostToDevice));CK(cudaMemcpy(dlw,wlut,64,cudaMemcpyHostToDevice));CK(cudaMemcpy(dlx,xlut,64,cudaMemcpyHostToDevice));float*y[3],*ss[3];int8_t*q[3];for(int i=0;i<3;i++){CK(cudaMalloc(&y[i],C*4));CK(cudaMalloc(&ss[i],N*2*4));CK(cudaMalloc(&q[i],C));}CK(cudaMemset(bad,0,32));region<0,true><<<16,256>>>(dw,dx,ds,dlw,dlx,y[0],bad);region<1,true><<<16,256>>>(dw,dx,ds,dlw,dlx,y[1],bad);direct<<<C/256,256>>>(dw,dx,ds,y[2]);for(int i=0;i<3;i++)quant<<<dim3(N,2),128>>>(y[i],q[i],ss[i]);CK(cudaGetLastError());CK(cudaDeviceSynchronize());unsigned long long counts[4];CK(cudaMemcpy(counts,bad,32,cudaMemcpyDeviceToHost));std::vector<int8_t>hq[3];std::vector<float>hs[3];for(int i=0;i<3;i++){hq[i].resize(C);hs[i].resize(N*2);CK(cudaMemcpy(hq[i].data(),q[i],C,cudaMemcpyDeviceToHost));CK(cudaMemcpy(hs[i].data(),ss[i],N*2*4,cudaMemcpyDeviceToHost));}for(int a=0;a<3;a++){std::vector<float>hy(C);CK(cudaMemcpy(hy.data(),y[a],C*4,cudaMemcpyDeviceToHost));char name[80];sprintf(name,"k16-prefix-mode%d.bin",a);FILE*f=fopen(name,"wb");if(!f||fwrite(hy.data(),4,C,f)!=C)return 4;fclose(f);sprintf(name,"k16-q8-mode%d.bin",a);f=fopen(name,"wb");if(!f||fwrite(hq[a].data(),1,C,f)!=C)return 4;fclose(f);sprintf(name,"k16-q8-scale-mode%d.bin",a);f=fopen(name,"wb");if(!f||fwrite(hs[a].data(),4,N*2,f)!=N*2)return 4;fclose(f);}const char*names[]={"k16-weights.bin","k16-activations.bin","k16-activation-scales.bin"};std::vector<uint8_t>*inputs[]={&w,&x,&sc};for(int a=0;a<3;a++){FILE*f=fopen(names[a],"wb");if(!f||fwrite(inputs[a]->data(),1,inputs[a]->size(),f)!=inputs[a]->size())return 4;fclose(f);}int qbad[2]={},sbad[2]={};for(int a=0;a<2;a++){for(int i=0;i<C;i++)qbad[a]+=hq[a][i]!=hq[2][i];for(int i=0;i<N*2;i++)sbad[a]+=memcmp(&hs[a][i],&hs[2][i],4)!=0;}printf("{\"status\":\"%s\",\"M\":256,\"N\":64,\"K\":32,\"groups\":2,\"group_slots\":16,\"word_checks\":49152,\"domain_errors\":%llu,\"gate_errors\":%llu,\"up_errors\":%llu,\"silu_errors\":%llu,\"q8_errors\":[%d,%d],\"q8_scale_errors\":[%d,%d],\"weight_bytes\":4096,\"activation_bytes\":1024,\"activation_scale_bytes\":128,\"label_tables_bytes\":128,\"scope\":\"actual raw paired two-bit weight nibbles and raw E2M1 activation nibbles; two independent E4M3 16-slot scale groups; four TF32 K8 serial group instructions vs two native MXFP4 K64 GU instructions; complete 128-feature maximum-normalized Q8 observer; one generated matrix, no learned-model acceptance\"}\n",counts[0]||counts[1]||counts[2]||counts[3]||qbad[0]||qbad[1]||sbad[0]||sbad[1]?"fail":"pass",counts[0],counts[1],counts[2],counts[3],qbad[0],qbad[1],sbad[0],sbad[1]);return counts[0]||counts[1]||counts[2]||counts[3]||qbad[0]||qbad[1]||sbad[0]||sbad[1]?2:0;}
